ee:message.ee:set-payload:
%dw 2.0
import * from dw::core::Strings
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
var inputBody = payload.CreateIncidentInput.Create
output application/xml writeDeclaration=false
---
soapenv#Envelope @("xmlns:urn": "urn:ETB_IntegracionMDM_WS"): {
    soapenv#Header: {
        "urn:AuthenticationInfo": {
			"urn:userName": p('mdm-remedy.credentials.user'),
            "urn:password": p('mdm-remedy.credentials.password'),
            "urn:authentication": null,
            "urn:locale": null,
            "urn:timeZone": null
        }
    },
    soapenv#Body: {
            "urn:Create": inputBody mapObject  (value,key,index) -> { 
                    ("urn:" ++ key) : value }
    } 
}

%dw 2.0
output application/json
---
{
  "CreateIncidentOutput": {
    "WSResponseHeader2": {
      "System": {
        "name": "MuleSoft",
        "correlationID": correlationId,
        "processingServer": "MuleSoft MDM"
      },
      "Service": {
        ("status": "PASS") if(payload.Envelope.Body.CreateResponse.Aknowledge == "Exitoso"),
        "responseDate": now() >> "America/Bogota"
      }
    },
    "CreateResponse": payload.Envelope.Body.CreateResponse
  }
}
